class Playground(World):
    def __init__(self):
        super().__init__()
        self._id = 0

    def next_id(self) -> int:
        self._id += 1
        return self._id

    def on_hero_enter_region(self, pos, region_id):
        super().on_hero_enter_region(pos, region_id)
        current_game().log('玩家进入了区域 ' + region_id)
        return
    
        r = self.loaded_regions[region_id]
        if len(r.nb_offsets) == 1:
            offset = next(iter(r.nb_offsets.values()))
            self.load_region(to_saved_region(_DATA, self.next_id(), {region_id: vec2i(offset.x, 0)}))



class TestMob(Mob):
    def __init__(self) -> None:
        super().__init__()
        self.with_level(2, 'beast')

    def act(self, context: dict) -> Future[float]:
        yield
        return 2.0

    @property
    def char(self) -> str:
        # return "🪳"
        return "🐍"


def to_saved_region(data: dict, index: int, nb_offsets: dict) -> dict:
    return {
        'id': f'playground_{index}',
        'width': data['width'],
        'height': data['height'],
        'nb_offsets': nb_offsets,
        'tiles': {
            'mask': array2d[bool](data['width'], data['height'], default=True),
            't_ground': array2d[int].fromlist(data['t_ground']),
            't_floor': array2d[int].fromlist(data['t_floor']),
            't_plant': array2d[int].fromlist(data['t_plant']),
            't_block': array2d[int].fromlist(data['t_block']),
        }
    }


def build_world():
    world = Playground()
    # 加载初始区域
    world.load_region(to_saved_region(_DATA, world.next_id(), {}))

    # 创建英雄
    if 0:
        world.load_region(to_saved_region(_DATA, world.next_id(), {'playground_1': vec2i(18, 0)}))
        world.load_region(to_saved_region(_DATA, world.next_id(), {'playground_1': vec2i(-18, 0)}))
        hero = world.spawn_actor(backend.Hero, vec2i(4, 5))

        # 在英雄附近随机位置放置一个怪物
        def random_place(T: type[Actor]):
            for pos, dist in world.bfs(hero.pos):
                if dist < 3:
                    continue
                if dist > 10 or random.random() < 0.1:
                    world.spawn_actor(T, pos)
                    return pos
            assert False, "No place to spawn"

        random_place(TestMob)
    else:
        hero = world.spawn_actor(backend.Hero, vec2i(13, 30))

    ############################################################
    
    ShortSword = Weapon(
        name=tr('item.short_sword'),
        desc=tr('desc.deal_{}_damage').format('2-4'),
        min_dmg=2,
        max_dmg=4,
        modifiers={
            'MaxHP+': 10,
            'dmg_types["cold"].reduction_pct+': 0.2,
            'dmg_types["fire"].reduction_pct+': 0.1,
            'dmg_types["lightning"].reduction_pct+': 0.05,
            'dmg_types["poison"].reduction_pct+': 0.04,
            'dmg_types["curse"].reduction_pct+': 0.1,
        },
        triggers={
            'on_hero_move': Effect.from_config(
                effects=[
                    'current_game().hero.add_hp(1)'
                ]
            )
        }
    )

    SmallHealingPotion = Item(
        name=tr('item.small_healing_potion'),
        desc=tr('desc.restore_{}_hp').format('15%'),
        actions={
            tr('ui.drink'): Effect.from_config(
                effects=[
                    'user.add_hp(user.stats.MaxHP * 15 // 100)',
                    common_fx.DeleteItem(),
                ],
            ),
            tr('ui.drop'): common_fx.DeleteItem(),
        }
    )


    hero.inventory.items[0].set(SmallHealingPotion)
    # hero.inventory.items[1].set(ShortSword)
    hero.equipments.weapon.set(ShortSword)

    hero.update_stats()
    return world, hero